"""Random small-alphabet strings and well-formed patterns built from
literal-or-dot atoms, each optionally starred."""

import string

ALPHABET = "ab"


def _random_pattern(rng, max_atoms):
    n_atoms = rng.randint(0, max_atoms)
    parts = []
    for _ in range(n_atoms):
        atom = "." if rng.random() < 0.3 else rng.choice(ALPHABET)
        parts.append(atom)
        if rng.random() < 0.4:
            parts.append("*")
    return "".join(parts)


def _random_string(rng, max_len):
    n = rng.randint(0, max_len)
    return "".join(rng.choice(ALPHABET) for _ in range(n))


def generate(rng, count):
    builders = (_random_pair, _string_from_pattern_ish, _star_heavy)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _tok(text):
    return text if text else "_"


def _case(name, pairs, description=""):
    lines = ["%s %s" % (_tok(s), _tok(p)) for s, p in pairs]
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _random_pair(rng, index):
    pairs = [(_random_string(rng, 6), _random_pattern(rng, 5))
             for _ in range(4)]
    return _case("random strings against random patterns #%d" % index, pairs)


def _string_from_pattern_ish(rng, index):
    # Strings built from the same alphabet as a plausibly-matching pattern,
    # biased towards strings the pattern was likely to actually accept.
    pairs = []
    for _ in range(4):
        base = rng.choice(ALPHABET)
        reps = rng.randint(0, 5)
        s = base * reps
        p = base + "*"
        pairs.append((s, p))
    return _case("repeated-character strings against a single star #%d"
                 % index, pairs)


def _star_heavy(rng, index):
    pairs = []
    for _ in range(3):
        p = _random_pattern(rng, 8)
        s = _random_string(rng, 8)
        pairs.append((s, p))
    return _case("longer patterns chaining several star groups #%d" % index,
                 pairs)
